"""F. Risk Recommendations: per-batch cards with risk left-border, checklist, chips & data-quality callout."""

import api_client as api
import streamlit as st
import theme
from components import (
    empty_state,
    fmt,
    format_date,
    info_callout,
    page_header,
    perf_badge,
    risk_badge,
    safe,
    status_pill,
)

from sections.shared import visible_batches


def render() -> None:
    page_header(
        "Risk Recommendations & Governance",
        "Per-batch credit risk committee directives generated by the backend decision engine",
        show_batch_selector=True,
    )

    info_callout(
        "info",
        "<b>Governance principle:</b> DriftGuard never retrains models or modifies credit rules automatically. "
        "CRITICAL requires empirically confirmed performance degradation; input drift alone caps at HIGH.",
    )

    with st.spinner("Loading batch recommendations…"):
        batches = visible_batches(safe(lambda: api.get("/batches"), [], retry_key="rec_b") or [])
    analysed = [b for b in batches if b.get("latest_job_id")]
    if not analysed:
        empty_state(
            "NO RECOMMENDATIONS",
            "No analysed batches yet",
            "Run drift analysis on at least one production batch to generate committee recommendations.",
        )
        return

    # Sort newest batch_date first
    analysed.sort(
        key=lambda b: (b.get("batch_date") or "", b.get("uploaded_at") or "", b["batch_id"]),
        reverse=True,
    )

    for b in analysed:
        rec = safe(lambda jid=b["latest_job_id"]: api.get(f"/recommendations/{jid}"))
        if not rec:
            continue
        risk_cat = rec.get("risk_category") or "LOW RISK"
        fg, _ = theme.risk_color(risk_cat)
        alert_text = rec.get("alert_type") or "Standard monitoring"
        alert_tone = {
            "LOW RISK": "low",
            "MEDIUM RISK": "medium",
            "HIGH RISK": "high",
            "CRITICAL RISK": "critical",
        }.get(risk_cat, "neutral")

        actions_html = "".join(
            f'<div style="display:flex;gap:8px;align-items:flex-start;padding:4px 0;font-size:13px;color:{theme.TEXT};">'
            f'<span style="color:{fg};font-weight:700;">☐</span><span>{a}</span></div>'
            for a in rec.get("recommended_actions", [])
        )
        affected = rec.get("affected_features") or []
        affected_html = (
            "".join(f'<span class="dg-chip">{feat}</span>' for feat in affected)
            if affected
            else f'<span style="font-size:12px;color:{theme.MUTED};">None above moderate threshold</span>'
        )
        low_impact = rec.get("low_impact_drift_features") or []
        dq_html = ""
        if low_impact:
            dq_chips = "".join(
                f'<span class="dg-chip" style="background:#FFFBEB;border-color:#FDE68A;color:#92400E;">{feat}</span>'
                for feat in low_impact
            )
            dq_html = (
                f'<div style="margin-top:10px;padding-top:10px;border-top:1px solid #F1F5F9;">'
                f'<div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.04em;color:#D97706;margin-bottom:4px;">Check data quality (strong drift, low DIS)</div>'
                f"{dq_chips}</div>"
            )

        st.markdown(
            f"""
            <div class="dg-card" style="border-left:4px solid {fg};">
                <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:10px;">
                    <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
                        <span style="font-size:16px;font-weight:600;color:{theme.INK};">{b['batch_id']}</span>
                        <span style="font-size:12px;color:{theme.MUTED};">{format_date(b.get('batch_date'))}</span>
                        {risk_badge(risk_cat)}
                        {perf_badge(rec.get('performance_state'))}
                    </div>
                    <div style="display:flex;align-items:center;gap:10px;">
                        <span style="font-size:13px;font-weight:700;color:{theme.INK};font-variant-numeric:tabular-nums;">DIS {fmt(rec.get('overall_dis'))}</span>
                        {status_pill(alert_text, alert_tone, dot=False)}
                    </div>
                </div>
                <div style="font-size:14px;font-weight:600;color:{theme.INK};margin-bottom:8px;">
                    {rec.get('recommendation', '')}
                </div>
                <div style="margin-bottom:10px;">{actions_html}</div>
                <div style="padding-top:8px;border-top:1px solid #F1F5F9;">
                    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.04em;color:{theme.MUTED};margin-bottom:4px;">Affected features</div>
                    {affected_html}
                </div>
                {dq_html}
            </div>
            """,
            unsafe_allow_html=True,
        )
